package pe.vichaval.gestionriego.riego.controller;import jakarta.validation.Valid;import org.springframework.stereotype.*;import org.springframework.ui.*;import org.springframework.validation.*;import org.springframework.web.bind.annotation.*;import pe.vichaval.gestionriego.parcela.repository.*;import pe.vichaval.gestionriego.riego.dto.*;import pe.vichaval.gestionriego.riego.entity.*;import pe.vichaval.gestionriego.riego.repository.*;@Controller@RequestMapping("/turnos")public class TurnoRiegoWebController{private final TurnoRiegoRepository r;private final ParcelaRepository p;public TurnoRiegoWebController(TurnoRiegoRepository r,ParcelaRepository p){this.r=r;this.p=p;}@GetMapping String list(Model m){m.addAttribute("turnos",r.findAll());return "riego/list";}@GetMapping("/nuevo")String form(Model m){m.addAttribute("form",new TurnoForm());m.addAttribute("parcelas",p.findAll());return "riego/form";}@PostMapping String save(@Valid@ModelAttribute("form")TurnoForm f,BindingResult b,Model m){if(!b.hasErrors()){var fin=f.getHoraInicio().plusMinutes(f.getDuracionMinutos());if(r.hayCruce(f.getFecha(),f.getHoraInicio(),fin))b.reject("cruce","Existe otro turno en ese horario");else{String c="TR-%04d".formatted(r.count()+1);r.save(new TurnoRiego(c,f.getFecha(),f.getHoraInicio(),fin,f.getObservaciones(),p.findById(f.getParcelaId()).orElseThrow()));return "redirect:/turnos";}}m.addAttribute("parcelas",p.findAll());return "riego/form";}}